// Support for the tests that run against the OFFICIAL Supabase local stack (Supabase CLI + Docker): the real Auth service
// (GoTrue), the real REST layer (PostgREST), the real Postgres image and the real mail-testing service (Mailpit).
//
// Nothing here is the project's own emulator. The stack is started with `supabase start` (see supabase/README.md) and
// these tests only talk to it over HTTP and over the Postgres port. The local stack's keys are generated by the CLI for
// a disposable local database; they are read at run time from `supabase status` or from environment variables and are
// never written into a file. Every address and number used is synthetic.
import { execFileSync } from "node:child_process";
import { createHmac, randomBytes } from "node:crypto";
import pg from "pg";

/** Reads the running stack's settings, or returns null when there is no stack (the tests then skip, never pass). */
export function readStack() {
  const env = process.env;
  if (env.M1_STACK_URL && env.M1_STACK_ANON_KEY && env.M1_STACK_DB_URL) {
    return {
      url: env.M1_STACK_URL,
      anonKey: env.M1_STACK_ANON_KEY,
      serviceKey: env.M1_STACK_SERVICE_KEY ?? null,
      dbUrl: env.M1_STACK_DB_URL,
      jwtSecret: env.M1_STACK_JWT_SECRET ?? null,
      mailUrl: env.M1_STACK_MAIL_URL ?? "http://127.0.0.1:54324",
    };
  }
  try {
    const cli = env.SUPABASE_CLI || "supabase";
    const out = execFileSync(cli, ["status", "-o", "json"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"], timeout: 60_000 });
    const status = JSON.parse(out.slice(out.indexOf("{")));
    if (!status.API_URL || !status.ANON_KEY || !status.DB_URL) return null;
    return {
      url: status.API_URL,
      anonKey: status.ANON_KEY,
      serviceKey: status.SERVICE_ROLE_KEY ?? null,
      dbUrl: status.DB_URL,
      jwtSecret: status.JWT_SECRET ?? null,
      mailUrl: status.MAILPIT_URL ?? status.INBUCKET_URL ?? "http://127.0.0.1:54324",
    };
  } catch {
    return null;
  }
}

export const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
export const PASSWORD = "A-long-synthetic-passphrase-1";
let counter = 0;
export const uniqueEmail = (label) => `${label}.${Date.now().toString(36)}${randomBytes(2).toString("hex")}${counter++}@example.test`;

/** A tiny client for the Auth and REST HTTP APIs, with the anon key unless a bearer token is given. */
export function makeApi(stack) {
  async function call(path, { method = "GET", body, token, headers = {}, key = stack.anonKey } = {}) {
    const response = await fetch(`${stack.url}${path}`, {
      method,
      headers: { apikey: key, ...(token ? { authorization: `Bearer ${token}` } : {}), ...(body !== undefined ? { "content-type": "application/json" } : {}), ...headers },
      body: body !== undefined ? JSON.stringify(body) : undefined,
    });
    const text = await response.text();
    let json = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      /* not JSON */
    }
    return { status: response.status, json, text, headers: response.headers };
  }
  return { call };
}

/** Mailpit, the mail-testing service in the stack. */
export function makeMail(stack) {
  const base = stack.mailUrl.replace(/\/$/, "");
  async function messagesTo(address) {
    const response = await fetch(`${base}/api/v1/search?query=${encodeURIComponent(`to:${address}`)}`);
    const data = await response.json();
    return data.messages ?? [];
  }
  /** Waits for a message to an address (optionally with a subject fragment) and returns its HTML and links. */
  async function waitFor(address, { subject, after = 0, timeoutMs = 15_000 } = {}) {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      const found = (await messagesTo(address)).filter((m) => (subject ? m.Subject.includes(subject) : true) && new Date(m.Created).getTime() >= after);
      if (found.length > 0) {
        const newest = found.sort((a, b) => new Date(b.Created) - new Date(a.Created))[0];
        const full = await (await fetch(`${base}/api/v1/message/${newest.ID}`)).json();
        const html = full.HTML ?? "";
        const links = [...html.matchAll(/href="([^"]+)"/g)].map((m) => m[1].replaceAll("&amp;", "&"));
        return { id: newest.ID, subject: newest.Subject, html, text: full.Text ?? "", links, count: found.length };
      }
      await sleep(250);
    }
    return null;
  }
  async function count(address) {
    return (await messagesTo(address)).length;
  }
  return { waitFor, count };
}

/** Pulls the token hash and type out of a confirmation, sign-in or recovery link. */
export function tokenFromLink(link) {
  const url = new URL(link);
  return { token_hash: url.searchParams.get("token_hash"), type: url.searchParams.get("type"), next: url.searchParams.get("next"), origin: url.origin, path: url.pathname };
}

/** Decodes a JWT payload (no verification: the tests read what the real service put in it). */
export function jwtClaims(token) {
  return JSON.parse(Buffer.from(token.split(".")[1], "base64url").toString("utf8"));
}

/** Signs a token with the stack's JWT secret, to test what the REST layer does with a bad or expired one. */
export function signJwt(secret, claims) {
  const b64 = (value) => Buffer.from(JSON.stringify(value)).toString("base64url");
  const head = b64({ alg: "HS256", typ: "JWT" });
  const body = b64(claims);
  const sig = createHmac("sha256", secret).update(`${head}.${body}`).digest("base64url");
  return `${head}.${body}.${sig}`;
}

// ---- RFC 6238 time-based one-time passwords (what an authenticator app computes) -----------------------------------
const B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
function base32Decode(input) {
  let bits = "";
  for (const char of input.replace(/=+$/, "").toUpperCase()) {
    const value = B32.indexOf(char);
    if (value < 0) throw new Error("bad base32");
    bits += value.toString(2).padStart(5, "0");
  }
  const bytes = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) bytes.push(parseInt(bits.slice(i, i + 8), 2));
  return Buffer.from(bytes);
}
export function totp(secret, time = Date.now(), step = 30, digits = 6) {
  const counter = Math.floor(time / 1000 / step);
  const buffer = Buffer.alloc(8);
  buffer.writeBigUInt64BE(BigInt(counter));
  const hmac = createHmac("sha1", base32Decode(secret)).update(buffer).digest();
  const offset = hmac[hmac.length - 1] & 0x0f;
  const code = (hmac.readUInt32BE(offset) & 0x7fffffff) % 10 ** digits;
  return String(code).padStart(digits, "0");
}

/** A Postgres connection as the stack's owner role (`postgres`): used to seed fixtures and to inspect, as a person with the database password would. */
export async function ownerClient(stack) {
  const client = new pg.Client({ connectionString: stack.dbUrl });
  await client.connect();
  return client;
}

/** Creates a user through the real Auth API and confirms the address through the real email. Returns the tokens. */
export async function signUpConfirmed({ api, mail, email, password = PASSWORD, redirectTo = "http://localhost:3000/auth/confirm?next=%2Faccount" }) {
  const started = Date.now() - 1000;
  const signup = await api.call(`/auth/v1/signup?redirect_to=${encodeURIComponent(redirectTo)}`, { method: "POST", body: { email, password } });
  if (signup.status >= 300) throw new Error(`signup failed: ${signup.status} ${signup.text}`);
  const message = await mail.waitFor(email, { after: started });
  if (!message) throw new Error("the confirmation email never arrived");
  const link = message.links.find((l) => l.includes("token_hash="));
  const { token_hash } = tokenFromLink(link);
  const verified = await api.call("/auth/v1/verify", { method: "POST", body: { type: "email", token_hash } });
  if (verified.status >= 300) throw new Error(`verify failed: ${verified.status} ${verified.text}`);
  return { email, password, userId: signup.json.user?.id ?? signup.json.id, session: verified.json };
}
